'use strict';
const $=id=>document.getElementById(id),KEY='taiwan-social-flashcards-v1',questions=FLASH_DATA.questions,topics=FLASH_DATA.topics,byId=new Map(questions.map(q=>[q.id,q]));
const defaults={unit:'all',topic:'all',deck:'all',size:'20',random:false};let record={},prefs={...defaults},round=null,revealed=false,storageOK=true;
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored){if(stored.record&&typeof stored.record==='object')for(const [id,status] of Object.entries(stored.record))if(byId.has(Number(id))&&['known','review'].includes(status))record[id]=status;if(stored.prefs)prefs={...defaults,...stored.prefs};const r=stored.round;if(r&&Array.isArray(r.ids)&&r.ids.length&&r.ids.every(id=>byId.has(id))&&Number.isInteger(r.index)&&r.index>=0&&r.index<=r.ids.length)round={ids:[...new Set(r.ids)],index:r.index,results:r.results&&typeof r.results==='object'?r.results:{}}}}catch(e){storageOK=false}
function save(){try{localStorage.setItem(KEY,JSON.stringify({record,prefs,round}))}catch(e){storageOK=false}$('storageWarning').textContent=storageOK?'':'目前瀏覽器無法儲存進度，仍可練習；關閉頁面後可能不會保留。'}
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function filtered(p){return questions.filter(q=>{const t=topics[q.topic];return(p.unit==='all'||t.unit===p.unit)&&(p.topic==='all'||String(q.topic)===p.topic)&&(p.deck==='all'||p.deck==='new'&&!record[q.id]||record[q.id]===p.deck)})}
function begin(p=prefs){prefs={...p};let list=filtered(prefs);if(prefs.random)list=shuffle(list);const limit=prefs.size==='all'?list.length:Number(prefs.size);round={ids:list.slice(0,limit).map(q=>q.id),index:0,results:{}};revealed=false;save();render()}
function filledSentence(text,show){return text.split(/(\{\{.*?\}\})/g).map(s=>s.startsWith('{{')?show?`<span class="answer">${escapeHtml(s.slice(2,-2))}</span>`:'<span class="blank" aria-label="空格"></span>':escapeHtml(s)).join('')}
function render(){const known=Object.values(record).filter(s=>s==='known').length;$('knownCount').textContent=known;const deckNames={all:'全部題目',new:'還沒標記',review:'再練習',known:'已熟悉'};$('modeTag').textContent=deckNames[prefs.deck]||'全部題目';$('topicLabel').textContent=prefs.topic!=='all'?(topics[Number(prefs.topic)]?.title||'全部主題'):prefs.unit==='1'?'第一單元':prefs.unit==='2'?'第二單元':prefs.unit==='extra'?'補充閱讀':prefs.unit==='mixed'?'跨課整合':'全部主題';
if(!round||!round.ids.length){empty();return}if(round.index>=round.ids.length){finish();return}$('study').hidden=false;$('summary').hidden=true;
const q=byId.get(round.ids[round.index]),t=topics[q.topic];$('roundLabel').textContent=(prefs.random?'隨機練習':'依課文順序')+' · 本回合';$('position').textContent=`${round.index+1} / ${round.ids.length}`;$('progress').style.width=((round.index+1)/round.ids.length*100)+'%';$('questionId').textContent=`NO. ${String(q.id).padStart(3,'0')}`;$('topic').textContent=t.title;$('source').textContent=t.source;$('blankCount').textContent=`${q.blanks} 個填空`;$('sentence').innerHTML=filledSentence(q.text,revealed);$('cardFace').textContent=revealed?'核對答案':'想一想';$('card').classList.toggle('revealed',revealed);$('answerNote').textContent=revealed?'綠色文字是答案。並列項目的順序可以互換。':'';$('hint').textContent=revealed?'想對了嗎？幫自己做個記號。':'先在心裡填空，再點按揭曉';$('actions').innerHTML=revealed?'<button class="primary secondary" id="markReview">↻ 再練習</button><button class="primary" id="markKnown">✓ 已熟悉</button>':'<button class="primary" id="reveal">我想好了，揭曉答案 ✦</button>';$('previous').disabled=round.index===0;$('next').textContent=round.index===round.ids.length-1?'回合結算 →':'下一張 →';save()}
function flip(){if(!round||round.index>=round.ids.length)return;revealed=!revealed;render()}
function move(delta){if(!round||!round.ids.length)return;round.index=Math.max(0,Math.min(round.ids.length,round.index+delta));revealed=false;save();render()}
function mark(status){if(!revealed||!round||round.index>=round.ids.length)return;const id=round.ids[round.index];record[id]=status;round.results[id]=status;move(1)}
function finish(){$('study').hidden=true;$('summary').hidden=false;const rs=Object.values(round.results),known=rs.filter(x=>x==='known').length,review=rs.filter(x=>x==='review').length,unmarked=round.ids.length-rs.length;$('summary').innerHTML=`<div class="big">🌱</div><p class="eyebrow">今天又往前了一點</p><h2>這一回合完成了！</h2><p>看過 ${round.ids.length} 張卡，讓腦袋休息一下也很好。</p><div class="results"><span><b>${known}</b>已熟悉</span><span><b>${review}</b>再練習</span><span><b>${unmarked}</b>未標記</span></div>${review?'<button class="primary" id="retryRound">再練這回合不熟的題目</button>':''}<button class="primary ${review?'secondary':''}" id="newRound">選擇下一回合 →</button><button class="quiet" id="backRound">回看本回合</button>`;save()}
function empty(){$('study').hidden=true;$('summary').hidden=false;$('summary').innerHTML='<div class="big">🍃</div><h2>這個範圍還沒有卡片</h2><p>選擇「全部題目」，或更換單元與主題。<br>揭曉答案後標記「再練習」，就能建立複習題庫。</p><button class="primary" id="newRound">更換練習設定</button>'}
function formPrefs(){return{unit:$('unitSelect').value,topic:$('topicSelect').value,deck:$('deckSelect').value,size:$('sizeSelect').value,random:$('randomSelect').checked}}
function updateTopics(selected='all'){const unit=$('unitSelect').value;$('topicSelect').innerHTML='<option value="all">全部主題</option>'+topics.filter(t=>unit==='all'||t.unit===unit).map(t=>`<option value="${t.id}">${escapeHtml(t.title)}</option>`).join('');$('topicSelect').value=selected;if(!$('topicSelect').value)$('topicSelect').value='all';updateCount()}
function updateCount(){$('filterCount').textContent=`符合目前設定：${filtered(formPrefs()).length} 題`}
function settings(){$('unitSelect').value=prefs.unit;$('deckSelect').value=prefs.deck;$('sizeSelect').value=prefs.size;$('randomSelect').checked=prefs.random;updateTopics(prefs.topic);$('preferences').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;switch(b.id){case'reveal':flip();break;case'markReview':mark('review');break;case'markKnown':mark('known');break;case'next':move(1);break;case'previous':move(-1);break;case'settings':case'newRound':settings();break;case'closeSettings':$('preferences').close();break;case'shuffle':if(round&&round.index<round.ids.length){const current=round.ids[round.index],done=round.ids.slice(0,round.index);round.ids=[...done,current,...shuffle(round.ids.slice(round.index+1))];prefs.random=true;save();render();$('shuffle').textContent='✓ 後續卡片已打亂';setTimeout(()=>$('shuffle').textContent='⇄ 打亂順序',1800)}break;case'retryRound':round={ids:round.ids.filter(id=>round.results[id]==='review'),index:0,results:{}};revealed=false;save();render();break;case'backRound':round.index=0;revealed=false;save();render();break;case'reset':if(confirm('要清除所有閃卡的熟悉度與回合進度嗎？此動作無法復原。')){record={};prefs={...defaults};$('preferences').close();begin()}break}});
$('unitSelect').addEventListener('change',()=>updateTopics());['topicSelect','deckSelect','sizeSelect','randomSelect'].forEach(id=>$(id).addEventListener('change',updateCount));$('prefsForm').addEventListener('submit',e=>{e.preventDefault();const p=formPrefs();$('preferences').close();begin(p)});
document.addEventListener('keydown',e=>{if($('preferences').open||/^(INPUT|SELECT|TEXTAREA|BUTTON|A)$/.test(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();flip()}if(e.key==='ArrowRight'){e.preventDefault();move(1)}if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}});
if(!round)begin();else render();
